-- --------------------------------------------------------------------------
-- spell_ranks: rank chains for the launched traps.
--
-- SkillLineAbility.SupercededBySpell is 0 on every retail trap row, so
-- the client does not collapse trap ranks by itself -- Player::addSpell
-- walks spell_ranks and unlearns the superseded rank.  Without these
-- rows all 19 launcher buttons would sit in the spellbook at once.
-- --------------------------------------------------------------------------
DELETE FROM `spell_ranks` WHERE `spell_id` IN (200700, 200701, 200702, 200704, 200705, 200706, 200707, 200708, 200709, 200710, 200711, 200712, 200713, 200714, 200715, 200716, 200717);
-- Freezing Trap: 3 ranks
INSERT INTO `spell_ranks` (`first_spell_id`, `spell_id`, `rank`) VALUES (200700, 200700, 1), (200700, 200701, 2), (200700, 200702, 3);
